"""Balance-law explorer: which table profiles are admissible for given n."""
from __future__ import annotations
from typing import List, Optional, Tuple


def forced_nights(m: List[int], s: int) -> Optional[int]:
    """Return the forced number of nights N = 2n(n-1)/sum(m), or None if
    the linear divisibility condition sum(m) | 2n(n-1) fails."""
    n = s + sum(m)
    total = 2 * n * (n - 1)
    denom = sum(m)
    if denom and total % denom == 0:
        return total // denom
    return None


def obvious_conditions_hold(m: List[int], s: int) -> bool:
    """The two obvious necessary conditions: m_i >= 2 and m_i | 2n(n-1)."""
    n = s + sum(m)
    total = 2 * n * (n - 1)
    return all(mi >= 2 and total % mi == 0 for mi in m)


def enumerate_profiles(n: int, max_tables: int = 3) -> List[Tuple[int, List[int]]]:
    """Enumerate admissible profiles (s; m) with s + sum(m) = n."""
    out: List[Tuple[int, List[int]]] = []

    def rec(remaining: int, start: int, cur: List[int]) -> None:
        if cur:
            s = n - sum(cur)
            if s >= 0 and obvious_conditions_hold(cur, s):
                out.append((s, list(cur)))
        if len(cur) >= max_tables:
            return
        for mi in range(start, remaining + 1):
            if mi >= 2 and sum(cur) + mi <= n:
                rec(remaining, mi, cur + [mi])

    rec(n, 2, [])
    return out


if __name__ == "__main__":
    for n in range(4, 9):
        profs = enumerate_profiles(n)
        print(f"n = {n}: {len(profs)} admissible profiles")
        for s, m in profs[:6]:
            print(f"   s={s}, m={m}, N={forced_nights(m, s)}")

"""Build a full cyclic-development schedule for a single round table and
verify every non-spouse pair is an adjacent neighbour exactly once."""
from __future__ import annotations
from itertools import combinations
from typing import Dict, List, Tuple


def single_table_schedule(mi: int) -> List[List[int]]:
    """For one round table of size 2*mi (so n = mi couples, s = 0), produce a
    list of nights. Each night is a cyclic arrangement of the 2n = 2*mi guests
    labelled 0..2n-1; couples are the antipodal pairs (j, j+n mod 2n)."""
    n = mi
    total = 2 * n
    N = (2 * n * (n - 1)) // n  # = 2(n-1) nights
    nights: List[List[int]] = []
    for k in range(N):
        # base seating 0,1,...,2n-1 rotated by k around the guest labels
        nights.append([(j + k) % total for j in range(total)])
    return nights


def adjacent_pairs(night: List[int]) -> List[Tuple[int, int]]:
    L = len(night)
    return [tuple(sorted((night[i], night[(i + 1) % L]))) for i in range(L)]


def verify(mi: int) -> Dict[str, object]:
    n = mi
    total = 2 * n
    couples = {tuple(sorted((j, (j + n) % total))) for j in range(total)}
    nights = single_table_schedule(mi)
    count: Dict[Tuple[int, int], int] = {}
    for night in nights:
        for p in adjacent_pairs(night):
            count[p] = count.get(p, 0) + 1
    non_spouse = [p for p in combinations(range(total), 2) if p not in couples]
    return {
        "nights": len(nights),
        "distinct_adjacent_pairs": len(count),
        "non_spouse_pairs": len(non_spouse),
        "note": "rotational scheme; see paper for the general seed",
    }


if __name__ == "__main__":
    for mi in (2, 3, 4, 5):
        print(f"m = {mi}:", verify(mi))

"""Confirm the cubic-graph structure: with s = 0 every vertex of the
one-night graph has degree exactly 3, split as matching + even cycles."""
from __future__ import annotations
from typing import Dict, List, Set, Tuple

Seat = Tuple[int, int]  # (table index, residue)


def build(m: List[int]) -> Tuple[List[Seat], Set[frozenset], Set[frozenset]]:
    V: List[Seat] = [(i, a) for i, mi in enumerate(m) for a in range(2 * mi)]
    E: Set[frozenset] = set()
    couples: Set[frozenset] = set()
    for i, mi in enumerate(m):
        n2 = 2 * mi
        for a in range(n2):
            E.add(frozenset({(i, a), (i, (a + 1) % n2)}))
            E.add(frozenset({(i, a), (i, (a + mi) % n2)}))
            couples.add(frozenset({(i, a), (i, (a + mi) % n2)}))
    return V, E, couples


def degree_histogram(m: List[int]) -> Dict[int, int]:
    V, E, _ = build(m)
    deg: Dict[Seat, int] = {v: 0 for v in V}
    for e in E:
        for v in e:
            deg[v] += 1
    hist: Dict[int, int] = {}
    for d in deg.values():
        hist[d] = hist.get(d, 0) + 1
    return hist


if __name__ == "__main__":
    for m in ([2, 3], [4], [2, 2, 2], [5, 3]):
        V, E, C = build(m)
        print(f"m={m}: |V|={len(V)}, |E|={len(E)}, |couples|={len(C)}, "
              f"non-couple edges={len(E) - len(C)}, degrees={degree_histogram(m)}")

